-- Function: public.fn_get_classroom_vacancies
-- Backup generated on 2026-10-25 20:33:11

CREATE OR REPLACE FUNCTION public.fn_get_classroom_vacancies(p_tenant_id uuid, p_branch_id uuid DEFAULT NULL::uuid)  RETURNS TABLE(classroom_id uuid, classroom_name character varying, age_group character varying, capacity integer, current_enrolled bigint, pending_offers bigint)  LANGUAGE sql  STABLE AS $function$     SELECT          c.id AS classroom_id,         c.name AS classroom_name,         COALESCE(c.age_group, c.classroom_type, 'Toddler')::VARCHAR AS age_group,         COALESCE(c.capacity, 15) AS capacity,         (SELECT COUNT(*) FROM children ch WHERE ch.classroom_id = c.id AND ch.is_active = TRUE) AS current_enrolled,         (SELECT COUNT(*) FROM enrollment_pipeline_applications a WHERE a.target_classroom_id = c.id AND a.pipeline_stage IN ('UnderReview', 'OfferSent')) AS pending_offers     FROM classrooms c     WHERE c.tenant_id = p_tenant_id       AND (p_branch_id IS NULL OR c.branch_id = p_branch_id)     ORDER BY c.name; $function$ ;
